$erro='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 $nome=trim($_POST['name']??'');$tipo=($_POST['customer_type']??'individual')==='company'?'company':'individual';$nif=trim($_POST['nif']??'');$telefone=trim($_POST['phone']??'');$email=strtolower(trim($_POST['email']??''));$senha=(string)($_POST['password']??'');$morada=trim($_POST['address']??'');$cidade=trim($_POST['city']??'');$provincia=trim($_POST['province']??'');
 if($nome===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($senha)<8||$morada===''||$telefone==='')$erro='Preenche os campos obrigatórios. A palavra-passe deve ter pelo menos 8 caracteres.';
 else try{$pdo->beginTransaction();$st=$pdo->prepare("INSERT INTO customers (customer_type,name,nif,phone,email,password,address,city,province,active,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,1,NOW(),NOW())");$st->execute([$tipo,$nome,$nif?:null,$telefone,$email,password_hash($senha,PASSWORD_DEFAULT),$morada,$cidade?:null,$provincia?:null]);$id=(int)$pdo->lastInsertId();$pdo->commit();session_regenerate_id(true);$_SESSION['gpm_customer']=['id'=>$id,'name'=>$nome,'email'=>$email];flash('success','Conta criada com sucesso.');$dest=$_SESSION['gpm_after_login']??'pedidos.php';unset($_SESSION['gpm_after_login']);redirect($dest);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('GPM cadastro: '.$e->getMessage());$erro=str_contains(strtolower($e->getMessage()),'duplicate')?'Este email ou NIF já está registado.':'Não foi possível criar a conta. Confirma os dados e tenta novamente.';}
}
$tituloPagina='Criar conta';require __DIR__.'/includes/header-marketplace.php';
